import AVFoundation
import CoreMedia
import Foundation

/// The await-free reader and publisher for the peaks pass. Asset properties
/// are loaded by `MediaImporter.peaks`, which owns the async boundary.
extension MediaImporter {
    /// 2 since spec §11 SY-42: an MP3 whose encoder delay Core Audio leaves in
    /// is read past it, so every peaks file made before is made again once.
    static let peaksVersion = 2

    struct PeaksStamp: Codable, Equatable {
        let source: CacheStamp
        let version: Int

        init(_ source: CacheStamp) {
            self.source = source
            self.version = MediaImporter.peaksVersion
        }
    }

    static func readPeaksStamp(at url: URL) -> PeaksStamp? {
        guard let data = try? Data(contentsOf: url),
            let marker = try? JSONDecoder().decode(PeaksStamp.self, from: data),
            marker.version == peaksVersion
        else { return nil }
        return marker
    }

    static func peaksAreCurrent(for media: MediaSnapshot, stamp: CacheStamp?, in cacheDir: URL)
        -> Bool
    {
        guard let stamp,
            readPeaksStamp(at: peaksMarkerURL(for: media.id, in: cacheDir)) == PeaksStamp(stamp)
        else { return false }
        return loadPeaks(for: media.id, in: cacheDir) != nil
    }

    /// Intersect the selected track's target edits with its numeric extent.
    /// An explicitly empty edit is a gap. No segments means the ordinary
    /// unedited track, whose whole timeRange is required.
    static func expectedPeaksRanges(
        trackRange: CMTimeRange, segments: [AVAssetTrackSegment]
    ) -> [CMTimeRange]? {
        guard trackRange.isValid, trackRange.duration.isNumeric,
            CMTimeCompare(trackRange.duration, .zero) > 0 else { return nil }
        let targets = segments.isEmpty ? [trackRange] : segments.filter { !$0.isEmpty }
            .map { $0.timeMapping.target }
        var intervals: [CMTimeRange] = []
        for target in targets {
            guard target.isValid, target.duration.isNumeric else { return nil }
            let clipped = CMTimeRangeGetIntersection(trackRange, otherRange: target)
            if clipped.isValid, clipped.duration.isNumeric,
                CMTimeCompare(clipped.duration, .zero) > 0 { intervals.append(clipped) }
        }
        intervals.sort { CMTimeCompare($0.start, $1.start) < 0 }
        var merged: [CMTimeRange] = []
        for interval in intervals {
            if let last = merged.last,
                CMTimeCompare(interval.start, CMTimeRangeGetEnd(last)) <= 0 {
                merged[merged.count - 1] = CMTimeRangeFromTimeToTime(
                    start: last.start, end: CMTimeMaximum(CMTimeRangeGetEnd(last),
                                                          CMTimeRangeGetEnd(interval)))
            } else { merged.append(interval) }
        }
        return merged
    }

    /// Each range shifted by −lead and intersected with [0, +∞); empty ones
    /// dropped. `expectedPeaksRanges` stays in the track's own timeline; this
    /// is where the peaks of a delayed MP3 (`PeakBuckets`' `lead`) must reach.
    static func peaksRanges(_ ranges: [CMTimeRange], less lead: CMTime) -> [CMTimeRange] {
        guard lead != .zero else { return ranges }
        let after = CMTimeRange(start: .zero, duration: .positiveInfinity)
        return ranges.compactMap { range in
            let shifted = CMTimeRangeGetIntersection(
                CMTimeRange(start: CMTimeSubtract(range.start, lead), duration: range.duration),
                otherRange: after)
            guard shifted.isValid, !shifted.isEmpty else { return nil }
            return shifted
        }
    }

    @discardableResult
    static func writePeaks(
        for media: MediaSnapshot, asset: AVURLAsset, track: AVAssetTrack,
        expectedRanges: [CMTimeRange], stamp: CacheStamp?, into cacheDir: URL,
        pass: CachePass? = nil
    ) -> Bool {
        guard let reader = try? AVAssetReader(asset: asset) else { return false }
        // The MP3 encoder delay Core Audio left in (spec §11 SY-42): decoded
        // from 0 and placed at PTS − lead, so the priming falls before bucket 0.
        let lead = MP3Gapless.leadingTrim(of: asset.url, track: track)
        let output = AVAssetReaderTrackOutput(
            track: track,
            outputSettings: [
                AVFormatIDKey: kAudioFormatLinearPCM,
                AVLinearPCMBitDepthKey: 32,
                AVLinearPCMIsFloatKey: true,
                AVLinearPCMIsBigEndianKey: false,
                AVLinearPCMIsNonInterleaved: false,
            ])
        output.alwaysCopiesSampleData = false
        guard reader.canAdd(output) else { return false }
        reader.add(output)
        guard reader.startReading() else { return false }

        var peaks = PeakBuckets(duration: media.duration, lead: lead)
        while let sample = output.copyNextSampleBuffer() {
            if !peaks.add(sample) { break }
        }
        // A nil next buffer can mean either completion or decoder failure.
        // Cancelling first would erase that distinction.
        let status = reader.status
        reader.cancelReading()
        return finishPeaks(peaks, status: status,
                           expectedRanges: peaksRanges(expectedRanges, less: lead),
                           for: media, stamp: stamp, into: cacheDir, pass: pass)
    }

    /// The only publication path, shared by the actual reader and the probe.
    /// The directory, the `.bin`, its marker (or the `.bin`'s removal) and
    /// the post run inside one `CacheLedger.publish` — the directory too,
    /// because a save's swap can take the one made before the wait; answers
    /// whether it published.
    @discardableResult
    static func finishPeaks(
        _ peaks: PeakBuckets, status: AVAssetReader.Status,
        expectedRanges: [CMTimeRange], for media: MediaSnapshot,
        stamp: CacheStamp?, into cacheDir: URL, pass: CachePass? = nil
    ) -> Bool {
        guard status == .completed, !peaks.failed, peaks.acceptedFrames > 0,
            peaks.covers(expectedRanges), let stamp else { return false }
        let file = peaksURL(for: media.id, in: cacheDir)
        let marker = peaksMarkerURL(for: media.id, in: cacheDir)
        var published = false
        CacheLedger.shared.publish(in: cacheDir, for: pass) {
            guard ensureDirectory(file.deletingLastPathComponent()) else { return }
            guard (try? peaks.data.write(to: file, options: .atomic)) != nil else { return }
            guard writeStamp(PeaksStamp(stamp), to: marker) else {
                try? FileManager.default.removeItem(at: file)
                return
            }
            postCacheChange(media: media.id, kind: peaksKind)
            published = true
        }
        return published
    }
}
import Accelerate
import CoreMedia
import Foundation

extension MediaImporter {
    /// One Float32 maximum magnitude per 10 ms of the media record. A frame's
    /// bucket follows its PTS (so leading and internal edit gaps are kept)
    /// through an integer frame index: a buffer's PTS is rounded to a frame
    /// once, and each frame is placed by `⌊(startFrame + f) · 100 / rate⌋`,
    /// so where the decoder splits the PCM into buffers cannot move a frame
    /// across a bucket edge, and the same PCM under the same record duration
    /// always writes the same bytes (issue #285). Coverage follows decoded
    /// presentation timestamps, in seconds, independently of that storage
    /// bound, so a shorter record cannot certify an unread track tail.
    ///
    /// `lead` is the MP3 encoder delay Core Audio left in
    /// (`MP3Gapless.leadingTrim`, spec §11 SY-42): every buffer is placed, and
    /// its coverage counted, at its PTS − lead, so the recording's first frame
    /// is bucket 0's and the priming before it falls under the `bucket >= 0`
    /// rule. Zero for every other file, whose buffers are placed at their PTS.
    struct PeakBuckets {
        private var buckets: [Float]
        private var coverage: [(start: Double, end: Double,
                                startUnit: Double, endUnit: Double)] = []
        private(set) var acceptedFrames = 0
        private(set) var failed = false
        private let lead: CMTime

        init(duration: Ticks, lead: CMTime = .zero) {
            self.lead = lead
            let count = max(1, Int((Double(duration) / Double(ReelTime.perSecond)
                * Double(MediaImporter.peakBucketsPerSecond)).rounded(.up)))
            buckets = [Float](repeating: 0, count: count)
        }

        var data: Data { buckets.withUnsafeBufferPointer { Data(buffer: $0) } }

        /// A malformed nonempty buffer latches failure. No bytes from it
        /// contribute either waveform values or claimed coverage.
        mutating func add(_ sample: CMSampleBuffer) -> Bool {
            guard !failed else { return false }
            let frames = CMSampleBufferGetNumSamples(sample)
            guard frames >= 0 else { failed = true; return false }
            if frames == 0 { return true }
            guard CMSampleBufferIsValid(sample), CMSampleBufferDataIsReady(sample),
                let format = CMSampleBufferGetFormatDescription(sample),
                let asbd = CMAudioFormatDescriptionGetStreamBasicDescription(format)?.pointee,
                asbd.mFormatID == kAudioFormatLinearPCM,
                asbd.mSampleRate.isFinite, asbd.mSampleRate > 0,
                asbd.mBitsPerChannel == 32, asbd.mFramesPerPacket == 1,
                asbd.mChannelsPerFrame > 0,
                asbd.mFormatFlags & kAudioFormatFlagIsFloat != 0,
                asbd.mFormatFlags & kAudioFormatFlagIsPacked != 0,
                asbd.mFormatFlags & kAudioFormatFlagIsBigEndian == 0,
                asbd.mFormatFlags & kAudioFormatFlagIsNonInterleaved == 0,
                let block = CMSampleBufferGetDataBuffer(sample)
            else { failed = true; return false }
            let channels = Int(asbd.mChannelsPerFrame)
            let (samplesCount, samplesOverflow) = frames.multipliedReportingOverflow(by: channels)
            let (expectedBytes, bytesOverflow) = samplesCount.multipliedReportingOverflow(by: 4)
            guard !samplesOverflow, !bytesOverflow,
                asbd.mBytesPerFrame == channels * 4,
                asbd.mBytesPerPacket == asbd.mBytesPerFrame,
                CMBlockBufferGetDataLength(block) == expectedBytes,
                CMSampleBufferGetTotalSampleSize(sample) == expectedBytes,
                expectedBytes > 0
            else { failed = true; return false }
            let stamp = CMSampleBufferGetPresentationTimeStamp(sample)
            let time = lead == .zero ? stamp : CMTimeSubtract(stamp, lead)
            guard time.isNumeric, time.timescale > 0 else { failed = true; return false }
            let start = CMTimeGetSeconds(time)
            let end = start + Double(frames) / asbd.mSampleRate
            guard start.isFinite, end.isFinite, end > start else {
                failed = true; return false
            }
            var samples = [Float](repeating: 0, count: samplesCount)
            let copied = samples.withUnsafeMutableBytes { raw -> OSStatus in
                guard let base = raw.baseAddress else { return -1 }
                return CMBlockBufferCopyDataBytes(
                    block, atOffset: 0, dataLength: expectedBytes, destination: base)
            }
            guard copied == noErr, samples.allSatisfy({ $0.isFinite }) else {
                failed = true; return false
            }

            // Timestamp placement preserves genuine leading and internal edit
            // gaps. The PTS is rounded to a frame index once; every frame's
            // bucket follows from that integer index, never from float
            // seconds, so a buffer edge at k/100 s cannot floor to k − 1.
            // Group adjacent frames in each bucket for a vDSP maximum;
            // values above full scale are deliberately retained.
            let startFrame = (start * asbd.mSampleRate).rounded()
            guard startFrame.isFinite, abs(startFrame) < 9_007_199_254_740_992 else {
                failed = true; return false
            }
            func bucketOf(_ frame: Int) -> Double {
                floor((startFrame + Double(frame))
                      * Double(MediaImporter.peakBucketsPerSecond) / asbd.mSampleRate)
            }
            var frame = 0
            while frame < frames {
                let bucketDouble = bucketOf(frame)
                guard bucketDouble.isFinite, bucketDouble >= Double(Int.min),
                    bucketDouble < Double(Int.max) else { failed = true; return false }
                let bucket = Int(bucketDouble)
                var take = 1
                while frame + take < frames {
                    if bucketOf(frame + take) != bucketDouble { break }
                    take += 1
                }
                if bucket >= 0 && bucket < buckets.count {
                    var magnitude: Float = 0
                    samples.withUnsafeBufferPointer { buffer in
                        if let base = buffer.baseAddress {
                            vDSP_maxmgv(base + frame * channels, 1, &magnitude,
                                        vDSP_Length(take * channels))
                        }
                    }
                    buckets[bucket] = max(buckets[bucket], magnitude)
                }
                frame += take
            }
            acceptedFrames += frames
            // An exact integer timestamp such as 0/1 has no whole-second
            // uncertainty. Keep the decoded edge's own precision; an
            // unrelated buffer must not enlarge its allowance.
            let timestampUnit = time.value % Int64(time.timescale) == 0
                ? 0 : 1 / Double(time.timescale)
            let edgeUnit = max(1 / asbd.mSampleRate, timestampUnit)
            insertCoverage(start: start, end: end, unit: edgeUnit)
            return true
        }

        private mutating func insertCoverage(start: Double, end: Double, unit: Double) {
            var next = (start: start, end: end, startUnit: unit, endUnit: unit)
            var result: [(start: Double, end: Double,
                          startUnit: Double, endUnit: Double)] = []
            var inserted = false
            for old in coverage {
                if old.end < next.start - 1e-9 {
                    result.append(old)
                } else if next.end < old.start - 1e-9 {
                    if !inserted { result.append(next); inserted = true }
                    result.append(old)
                } else {
                    if old.start < next.start {
                        next.start = old.start
                        next.startUnit = old.startUnit
                    }
                    if old.end > next.end {
                        next.end = old.end
                        next.endUnit = old.endUnit
                    }
                }
            }
            if !inserted { result.append(next) }
            coverage = result
        }

        /// At each outer boundary permit at most its decoded PCM frame or
        /// fractional CMTime unit. Exact coverage needs no allowance. No
        /// allowance bridges an internal gap or reaches a whole bucket.
        func covers(_ expectedRanges: [CMTimeRange]) -> Bool {
            guard !failed, acceptedFrames > 0, !expectedRanges.isEmpty else { return false }
            for range in expectedRanges {
                guard range.isValid, range.start.isNumeric, range.duration.isNumeric,
                    CMTimeCompare(range.duration, .zero) > 0 else { return false }
                let start = CMTimeGetSeconds(range.start)
                let end = CMTimeGetSeconds(CMTimeRangeGetEnd(range))
                guard start.isFinite, end.isFinite, end > start else { return false }
                // A fractional target such as AAC's 1250/1000 can differ
                // from decoded frames by one millisecond. Exact boundaries
                // and exact full coverage do not need metadata tolerance.
                func roundingUnit(_ time: CMTime) -> Double {
                    time.value % Int64(time.timescale) == 0
                        ? 0 : 1 / Double(time.timescale)
                }
                guard coverage.contains(where: {
                    let startShortfall = max(0, $0.start - start)
                    let endShortfall = max(0, end - $0.end)
                    if startShortfall == 0 && endShortfall == 0 { return true }
                    let bucket = 1 / Double(MediaImporter.peakBucketsPerSecond)
                    let startUnit = max($0.startUnit, roundingUnit(range.start))
                    let endUnit = max($0.endUnit,
                                      roundingUnit(CMTimeRangeGetEnd(range)))
                    return (startShortfall == 0 ||
                            startUnit < bucket && startShortfall <= startUnit)
                        && (endShortfall == 0 ||
                            endUnit < bucket && endShortfall <= endUnit)
                }) else { return false }
            }
            return true
        }
    }
}

