import Foundation

/// The cached waveform, the plan's mix envelope, and how to ask either about a
/// moment — the arithmetic every reader of "how loud is this, there?" shares.
///
/// `cache/peaks/<media id>.bin` is one 32-bit float per 1/100 s of SOURCE
/// time: the largest magnitude the file reaches anywhere inside that bucket,
/// taken across every channel, PRE-FADER and deliberately unclamped
/// (`MediaImporter.peaks`, which says why max and not RMS). It is written by a
/// fire-and-forget task at open and import, so "not on disk yet" is an
/// ordinary answer and never means silence.
///
/// **Everything here was `private static` inside `SilenceDetector` until road
/// map 2 phase 5c.** Normalise Clip needs the same question answered — the
/// loudest the file gets over the window a clip actually plays — and the
/// scouts' warning was specific: the app ALREADY carries two project-time →
/// source-time conversions that disagree. `TimelineView.sourceTime` multiplies
/// by `clip.speed`, rounding the rate a second time; the one here divides the
/// plan segment's own `sourceDuration` by its `duration`, which IS the rate the
/// composition plays at, exactly. A third copy would have made it three, so the
/// four pieces moved out here instead and `SilenceDetector` calls them:
///
/// 1. `bucketTicks` — how much source time one float covers;
/// 2. `sourceTick` — project time under a segment, at the plan's resolved rate;
/// 3. `bucketIndex` — the floor, spelled out for negatives;
/// 4. the reversed mirror `window` applies, which is `ReverseMirror`'s.
///
/// The mirror is the piece a reader is most likely to drop — without it a
/// reversed clip is measured against the wrong end of its own file, which
/// reads as a plausible number and is simply wrong. It is no longer spelled
/// here: `ReverseMirror` is its one home and states the convention, the pivot
/// and what it costs (spec §11, D4-6).
///
/// **`envelope` arrived the same way, one phase later.** It is the plan's
/// piecewise-linear mix gain at a tick — the OTHER half of every level this app
/// computes, since a peak bucket is pre-fader and the level anyone means is
/// `peak × envelope`. Phase 5's meter wrote a second copy of it beside
/// `SilenceDetector`'s and its own doc admitted as much; the consolidation
/// merged the two here. Both readers ask the same question, the rule `audio.rs`
/// expresses by making a mute and a solo a ZERO envelope, and neither may grow
/// a private copy of the search again.
///
/// Nothing here is AppKit and nothing here decides anything: it is arithmetic
/// over a plan segment, an array of floats and a pair of ticks.
enum MediaPeaks {

    // MARK: - The grid

    /// One bucket of the peaks cache, in ticks of SOURCE time. Exactly 6000,
    /// and written as the division rather than as the number because
    /// `peakBucketsPerSecond` and `perSecond` each have exactly one home.
    static var bucketTicks: Ticks {
        ReelTime.perSecond / Ticks(MediaImporter.peakBucketsPerSecond)
    }

    // MARK: - Reading the cache

    /// One media's peaks read at most once, however many segments cite it —
    /// a `MediaCacheLoader` over `MediaImporter.loadPeaks`.
    static func loader(cacheDirectory: URL?) -> MediaCacheLoader<[Float]> {
        MediaCacheLoader(cacheDirectory: cacheDirectory) {
            MediaImporter.loadPeaks(for: $0, in: $1)
        }
    }

    // MARK: - Asking about a window

    /// The loudest bucket the project span `[from, to)` of `segment` reads, or
    /// 0 when it falls outside the file the cache was built from.
    ///
    /// `reversedPivot` is the media's model duration when the clip plays
    /// backwards and nil when it does not — `reversedPivot(for:in:)` is how a
    /// caller works it out. Both ends of the window land INSIDE buckets, so the
    /// answer can take in up to 10 ms of neighbouring source at each end: an
    /// overestimate, which is the conservative direction for both callers (a
    /// span is judged too loud to cut rather than cut wrongly; a clip is
    /// normalised a shade quiet rather than into clipping). `bucketTicks` is
    /// the cache's grid, the peaks' 10 ms unless a caller names another
    /// (`MediaSpeech.speechMax` names the 32 ms Silero chunk).
    static func peak(
        _ peaks: [Float], over segment: PlanSegment, from: Ticks, to: Ticks,
        reversedPivot: Ticks?, bucketTicks: Ticks = MediaPeaks.bucketTicks
    ) -> Float {
        guard
            let range = window(
                of: segment, from: from, to: to, reversedPivot: reversedPivot,
                bucketTicks: bucketTicks, count: peaks.count)
        else { return 0 }
        var loudest: Float = 0
        for index in range { loudest = max(loudest, peaks[index]) }
        return loudest
    }

    /// The bucket-index range a project span `[from, to)` of `segment` covers
    /// in a cache built at `bucketTicks` per bucket over `count` buckets, or
    /// nil when it falls outside the file the cache was built from — the
    /// whole of `peak`'s arithmetic, generalised over the bucket size so the
    /// 32 ms Silero grid asks the same question without a second copy of
    /// the reversed-mirror arithmetic.
    static func window(
        of segment: PlanSegment, from: Ticks, to: Ticks, reversedPivot: Ticks?,
        bucketTicks: Ticks, count: Int
    ) -> ClosedRange<Int>? {
        guard segment.duration > 0, segment.sourceDuration > 0, count > 0 else { return nil }
        let first = sourceTick(segment, at: from)
        let last = max(first, sourceTick(segment, at: to) - 1)

        var source = first...last
        if let pivot = reversedPivot {
            source = ReverseMirror.mirrored(source, about: pivot)
        }

        let lower = max(0, bucketIndex(source.lowerBound, bucket: bucketTicks))
        let upper = min(count - 1, bucketIndex(source.upperBound, bucket: bucketTicks))
        guard lower <= upper else { return nil }
        return lower...upper
    }

    /// The pivot a reversed clip's window is mirrored about, or nil when the
    /// clip plays forwards — `ReverseMirror.pivot` asked about a plan SEGMENT,
    /// which is the unit every caller here holds.
    ///
    /// `reversed` is deliberately NOT in the plan (a reversed clip and a
    /// forward one must produce byte-identical plan JSON, or the
    /// rebuild-vs-refresh test breaks), so it is read back off the clip. The
    /// clip is looked up at the top level first and then among every nest's
    /// clips (#64): clip ids are one space and `nests` is flat, so a clip
    /// inside a CLOSED nest, at any depth, is found and mirrored too.
    static func reversedPivot(for segment: PlanSegment, in snapshot: ProjectSnapshot) -> Ticks? {
        let clip = snapshot.clip(segment.clip)
            ?? snapshot.nests.lazy.compactMap { $0.clips.first { $0.id == segment.clip } }.first
        return clip.flatMap { ReverseMirror.pivot(for: $0, in: snapshot) }
    }

    /// Source time under a project tick, at the rate the plan resolved:
    /// `sourceDuration / duration` IS the speed, exactly, with no second
    /// rounding of `clip.speed` here.
    ///
    /// A RAMPED clip's one audio segment is one ×1 segment over its slot, so
    /// that rate would misplace a moment mid-clip: it reads `⌊S(t − start)⌋`
    /// off the segment's own map, checked once at plan decode (spec §11
    /// SR-20 (c), (d)). A segment with no ramp, or a map that failed its
    /// check, takes the expression below.
    static func sourceTick(_ segment: PlanSegment, at t: Ticks) -> Ticks {
        if let map = segment.ramp?.source {
            let read = map.source(atClip: Double(t - segment.start)).rounded(.down)
            return TimelineLayout.ticks(clamping: read)
        }
        guard segment.duration > 0 else { return segment.sourceIn }
        let offset =
            Double(t - segment.start) * Double(segment.sourceDuration) / Double(segment.duration)
        guard offset.isFinite else { return segment.sourceIn }
        return segment.sourceIn + TimelineLayout.ticks(clamping: offset.rounded(.down))
    }

    /// `floor(tick / bucket)`, correct for a negative tick — which a mirrored
    /// reversed window produces when the clip runs past the media's start.
    /// Swift's integer division truncates toward zero, so the negative half
    /// has to be spelled out.
    static func bucketIndex(_ tick: Ticks, bucket: Ticks = MediaPeaks.bucketTicks) -> Int {
        guard bucket > 0 else { return 0 }
        let quotient = tick >= 0 ? tick / bucket : -((-tick + bucket - 1) / bucket)
        return Int(max(min(quotient, Ticks(Int.max)), Ticks(Int.min)))
    }

    // MARK: - Asking the plan

    /// The mix envelope at a project tick, interpolated piecewise-linearly from
    /// one track's plan ramps: the gain the mix is applying there, with
    /// `volume`, the fades, volume actions and ducking already folded in by
    /// `audio.rs`.
    ///
    /// 1 when a track carries no ramps at all — a video track's `ramps` is nil —
    /// which is the same thing `audio.rs` means by an unmodified track. A tick
    /// before the first ramp reads that ramp's `from`, and one past the last
    /// reads its `to`, so the answer is defined over the whole timeline and not
    /// only over the extent the ramps cover.
    ///
    /// Binary search rather than a scan, because a long timeline's envelope has
    /// a ramp per fade edge and the meter asks this thirty times a second per
    /// track.
    ///
    /// **This is the app's ONE spelling of the mix rule** (the type's doc says
    /// why it is here rather than in either caller): `SilenceDetector` asks it
    /// what a moment SOUNDS like, multiplying a pre-fader peak bucket by it, and
    /// `LevelMeter` asks it what a metered track's pre-fader BUFFER becomes in
    /// the mix. Because the core expresses a mute and a solo as a zero envelope,
    /// both get silencing for free and neither carries a Swift copy of
    /// `audio.rs`'s `silenced` to drift from the original.
    static func envelope(_ ramps: [PlanRamp]?, at t: Ticks) -> Double {
        guard let ramps = ramps, !ramps.isEmpty else { return 1 }
        var low = 0
        var high = ramps.count - 1
        var found = -1
        while low <= high {
            let mid = (low + high) / 2
            if ramps[mid].start <= t {
                found = mid
                low = mid + 1
            } else {
                high = mid - 1
            }
        }
        guard found >= 0 else { return ramps[0].from }
        let ramp = ramps[found]
        guard ramp.duration > 0 else { return ramp.to }
        guard t < ramp.start + ramp.duration else { return ramp.to }
        let fraction = Double(t - ramp.start) / Double(ramp.duration)
        return ramp.from + (ramp.to - ramp.from) * fraction
    }
}

/// One media's cache read at most once, however many segments cite it.
///
/// A cache read is a whole-file `Data(contentsOf:)` and a forty-minute
/// screencast is a megabyte of floats, so a timeline with a dozen clips off
/// one recording must not read it a dozen times. A failure is remembered as
/// well as a success — `pending` is what a caller reports as "still
/// analysing" — because a missing file is a fact about this moment, not an
/// error to retry inside one pass. `MediaPeaks.loader` and
/// `MediaSpeech.loader` are the two it is built as.
///
/// It is a class rather than a struct on purpose: it is a cache, two
/// callers share one, and a value type would have made "did that read land
/// in MY copy?" a question anyone extending this has to ask.
final class MediaCacheLoader<Value> {
    private let cacheDirectory: URL?
    private let read: (UInt32, URL) -> Value?
    private var loaded: [UInt32: Value] = [:]
    /// Media whose cache was asked for and was not there.
    private(set) var pending: Set<UInt32> = []

    /// nil is a document with nowhere to keep caches, which answers every
    /// media as pending — the same answer as a cache that has not been
    /// written yet, and the correct one.
    init(cacheDirectory: URL?, read: @escaping (UInt32, URL) -> Value?) {
        self.cacheDirectory = cacheDirectory
        self.read = read
    }

    func value(for media: UInt32) -> Value? {
        if let cached = loaded[media] { return cached }
        if pending.contains(media) { return nil }
        guard let cacheDirectory = cacheDirectory,
              let value = read(media, cacheDirectory)
        else {
            pending.insert(media)
            return nil
        }
        loaded[media] = value
        return value
    }
}
import CoreMedia
import Foundation

/// The reversed mirror — the app's ONE spelling of "what does this clip show
/// there, when it plays backwards?" (spec §11, D4-6).
///
/// **The convention.** `Source::Media.reversed` measures the `in` point in the
/// REVERSED stream (`Source::Media` in `core/src/model.rs`), so a reversed
/// clip keeps its `in` and shows different frames. Everything the app holds
/// about the file — the peaks cache, the thumbnails, the decoded asset — is of
/// the FORWARD one, and nothing ever generates either for `cache/reversed/…`,
/// which is not a media entry at all. So a tick `p` measured in the played
/// stream reads the forward file at `pivot − p`, and the pivot is the media's
/// MODEL duration `T`: the number `in` is measured against, and the number
/// `ReverseRenderer` renders against, which is what makes the two line up.
///
/// **Why the core has none, and why this is not it.** `edit_clip.rs`'s
/// `set_reversed` argues the refusal: advancing `in` to keep the same frames
/// would be a second convention, and every trim, split and source-length
/// reader in the crate would have to know which one was in force. The mirror
/// is therefore a PRESENTATION question — which cached bucket, which decoded
/// stamp — and it belongs on this side. §10.6's fourth decision.
///
/// **Its three readers, which agreed by convention only until this file.**
/// `MediaPeaks.window` mirrors a bucket window (`lo = pivot − last`,
/// `hi = pivot − first`); `TimelineView.sourceTime` mirrors the tick a
/// filmstrip tile and a waveform column index the caches at; and
/// `ReverseRenderer.walkBackwards` mirrors the presentation stamps it writes.
/// Nothing asserted that the three matched, and `TimelineView` in fact did not
/// mirror at all until road map 7 §10's phase C.
/// `CompositionBuilder` deliberately has no mirror and needs none: it
/// substitutes the pre-rendered reversed asset, whose times already run in the
/// played direction.
///
/// **One tick high, on purpose.** A reversed tick `p` covers the forward
/// file's tick `T − 1 − p`, and this answers `T − p`. The cost is an extra
/// bucket at an exactly aligned window end and one blank waveform column at
/// the head of a whole-file reversed clip whose `T` is a bucket multiple; the
/// reason it stays is that `tools/proof/silence2_proof.py`'s claim 9 walks
/// these numbers tick-exact, so moving them would move a reference walk that
/// exists to catch this arithmetic drifting. Recorded in road map 7 §10.9.
///
/// Nothing here is AppKit, nothing reads a file and nothing decides anything:
/// it is one subtraction, in the three units its callers hold it in.
enum ReverseMirror {

    /// The pivot a clip's source times are mirrored about — the media's model
    /// duration — or nil when the clip plays forwards or its media is unknown.
    ///
    /// This function finds the pivot for ANY clip it is handed, and a clip
    /// inside a CLOSED nest reaches it too (#64): `MediaPeaks.reversedPivot`
    /// looks a segment's clip up among every nest's clips when the top level
    /// does not hold it, so silence detection and Normalize measure such a
    /// clip mirrored without the nest being opened.
    ///
    /// No check of the source KIND beyond `isReversed`, which only a `media`
    /// source can be true for.
    static func pivot(for clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Ticks? {
        guard clip.source.isReversed else { return nil }
        return snapshot.media(for: clip)?.duration
    }

    /// The forward file's tick under a tick of the reversed stream.
    ///
    /// May go negative — a reversed clip whose window runs past the media's
    /// start produces one, which `MediaPeaks.bucketIndex` is spelled out for.
    static func mirrored(_ tick: Ticks, about pivot: Ticks) -> Ticks {
        pivot - tick
    }

    /// A whole window mirrored: the ends swap, because the mirror reverses
    /// order. `MediaPeaks.window`'s `lo` and `hi`, exactly.
    static func mirrored(_ window: ClosedRange<Ticks>, about pivot: Ticks) -> ClosedRange<Ticks> {
        (pivot - window.upperBound)...(pivot - window.lowerBound)
    }

    /// The same subtraction in `CMTime`, for the renderer: the frame shown
    /// from `p` until `p'` in the source is written at `T − p'`, so the
    /// source's last frame lands at zero and the stamps ascend.
    ///
    /// `CMTime` subtraction carries its own timescale arithmetic, so the two
    /// sides need not share one — the pivot is in tick scale and a source
    /// stamp is in its track's.
    static func mirrored(_ time: CMTime, about pivot: CMTime) -> CMTime {
        pivot - time
    }
}

